import ASSEMBLE_BASE as a
from pathlib import Path
import re,json,collections
R,W=a.ROOT,a.WORK
def link(cid):
    fn={'S':'SOURCES.md','F':'RAW_FACTS.md','Q':'OPEN_QUESTIONS.md','E':'RAW_FACTS.md'}[cid[0]]
    return f'[{cid}]({fn}#{cid.lower()})'
def refs(ids):return ', '.join(link(a.mapping[x]) for x in ids if x in a.mapping)
def tidy(s):
    if s.lstrip().startswith('|'):return '\n'.join('- '+c.strip() for c in s.strip().strip('|').split('|') if c.strip())
    return s
def write(name,s): (R/name).write_text(s.rstrip()+'\n',encoding='utf-8')
def branch_block(branch,start,end=None):
    txt=a.texts[branch];i=txt.index(start);j=txt.find(end,i+len(start)) if end else len(txt)
    return a.norm(txt[i:j if j>=0 else len(txt)],branch)
def cid(old):return a.mapping[old]

# Consolidated collector facts, clearly distinct from external observations.
n=sum(r['type'] in ['F','I'] for r in a.records.values())
custom={}
def add_custom(key,title,text,source_ids,etype='INF'):
    global n
    n+=1;custom[key]={'id':f'F{n:03}','title':title,'text':text,'sources':source_ids,'type':etype}
