# Preserve substantive catalogues, process maps and reasoning without repeating registries.
raw+=['## Подробные тематические материалы и операционализация','Ниже сохранены карты, матрицы, контраргументы и программы проверки из обеих волн. Ссылки нормализованы. Это подробности базы, не самостоятельные результаты тестирования. Исторический W1-минимум/метрики уточнены консолидированными карточками выше.']
for branch,txt in a.texts.items():
    sections=re.split(r'(?m)(?=^## )',txt)
    kept=[]
    for sec in sections:
        head=sec.splitlines()[0] if sec.splitlines() else ''
        if re.search(r'реестр|^## .*Источники|^## .*источники|^## .*Источники|^## 1\. Реестр|^## 2\. Источники',head,re.I):continue
        if branch=='W1-04' and '5. Реестр' in head:continue
        if re.search(r'База фактов|Проверенные факты|Факты и ограничения|Фактические основания|Факты, которые|Факты, меняющие|Факты и подтвержд',head,re.I):continue
        if sec==sections[0]:continue
        # Source/fact cards now own the atomic paragraphs; leave surrounding reasoning.
        sec=re.sub(r'(?m)^\|\s*W[12]-\d{2}-[FSQIE]\d+\s*\|.*\n?','',sec)
        sec=re.sub(r'(?m)^(?:[-*]\s*)?\*{0,2}W[12]-\d{2}-[FSQIE]\d+[^\n]*\n?','',sec)
        sec=re.sub(r'(?m)^[-*]\s*\*{0,2}[QIE]\d+[^\n]*\n?','',sec)
        sec=re.sub(r'(?m)^\|[^\n]+\n\|[\s|:-]+\|\n(?=\s*\n|$)','',sec)
        if branch=='W2-04' and head.startswith('## K008'):continue
        kept.append(sec)
    body=a.norm('\n'.join(kept),branch)
    # Embedded headings must not create duplicate canonical F/S/Q/E anchors.
    body=re.sub(r'(?m)^#{1,6} ([SFEQ]\d{3})\b',r'#### Подробность \1',body)
    raw+=['## Материал '+branch, f'Происхождение: [{paths_label(branch)}]({a.paths[branch].relative_to(R).as_posix()}).' if False else f'Происхождение: [{branch}]({a.paths[branch].relative_to(R).as_posix()}).',body]

