    for ident in aliases:
        r=a.records[ident]
        src+=['**Наблюдение доступа '+ident+'**',tidy(a.norm(r['text'],r['branch']))]
    src+=['Связанные F: '+(', '.join(link(x) for x in sorted(set(related))) if related else 'контекст/поисковый маршрут или неиспользованное для положительного утверждения ограничение доступа')+'.']
