q=['# OPEN_QUESTIONS — конкретный остаток исследования','Проверка/сборка: 23.10.2026, Europe/Moscow. Ни интервью, ни пилоты/UX-тесты не проведены. Вопросы — не выводы об отсутствии функций. Веточные Q сохранены для трассировки; актуальное решающее действие задано ниже и в консолидированных Q. Прежнее отсутствие полного PDF закрыто; новый поиск ради него не нужен.']
def route(s):
    if re.search(r'бюджет|подпис|закуп|покупател',s,re.I):return 'Владелец закупки/бюджета конкретного предприятия','получить схему закупки, лицо с полномочиями и согласованные критерии успеха пилота; не выводить покупателя из должности пользователя'
    if re.search(r'диспетчер|первичный получател|резервный|постоянн.*пост|круглосуточн',s,re.I):return 'Руководитель участка/смены и ОТ','получить матрицу получателей и замещения, расписание поста, полномочия и рабочий канал; сверить с конкретной сменой/событием'
    if re.search(r'владеет поток|владеет.*камер|доступны ли',s,re.I):return 'Владельцы камер/АСУТП/ИТ и безопасности площадки','инвентаризировать потоки и права доступа, показать доступный технический маршрут и согласованного владельца'
    if re.search(r'оспар|апелля|исправ|санкц|рабочи|подрядчик',s,re.I):return 'Работник/подрядчик, мастер и ОТ','разобрать конкретный спорный эпизод: доступ к оригиналу, возражение, проверяющий, причина решения, история, ответ и исправление последствий; сопоставить ответы ролей с обезличенной карточкой'
    if re.search(r'LinQ|SDK|модел|FPS|конвер|инференс',s,re.I):return 'Техническая команда/постановщик','получить точные доступы и версии; выполнить документированный пробный прогон разрешённого материала на LinQ; сохранить вход/выход/логи/замеры'
    if re.search(r'данн|согласи|прав|лицензи|хран|географ|VM|публич|удален|удалени|файл|биомет',s,re.I):return 'Владелец материала, постановщик/провайдер и ответственный за обработку','получить документы/ответ для конкретных файлов, операций, получателей и аудитории; заполнить карту переходов, хранения и доступа; не выводить разрешение из общей лицензии/марки ускорителя'
    if re.search(r'Vizor|IVA|аналог|конкур|Platform|re-arm|эпизод|track',s,re.I):return 'Команда исследования/представитель конкретного продукта','запросить руководство либо запись штатного UI для точной сборки; повторить указанный сценарий, сохранить состояния/историю; отсутствие ответа оставить Н/П'
    if re.search(r'Росстат|538|отрасл|2024|коэффициент',s,re.I):return 'Аналитик статистики','при необходимости получить оригинальную визуальную таблицу/сноски и совместимый знаменатель; до этого не публиковать отраслевой рейтинг'
    return 'Предметный владелец участка, мастер/ОТ и затронутые работники','провести walkthrough по недавнему конкретному событию с независимым ответом ролей и проверкой обезличенной карточки/регламента; сохранить различия ответов'
for ident,r in sorted(a.records.items(),key=lambda kv:a.mapping[kv[0]]):
    if r['type']!='Q':continue
    s=a.norm(r['text'],r['branch']);owner,method=route(s)
    q+=['### '+a.mapping[ident],f'Происхождение: `{ident}`, [{r["branch"]}]({r["path"]}). Статус: **открыто для конкретной площадки/версии/материала**.',tidy(s),'Владелец ответа: '+owner+'. Процедура: '+method+'.','Зависимое решение и конкретный требуемый артефакт указаны в вопросе. До ответа соответствующая возможность/эффект остаётся условной; ответ на общем сайте не заменяет этот артефакт.']
qn=sum(r['type']=='Q' for r in a.records.values());dispatch={}
def addq(key,title,decision,method,status='открыто'):
    global qn
    qn+=1;num=f'Q{qn:03}';dispatch[key]=num
    q.extend(['### '+num,'**'+title+'**. Статус: '+status+'.','Зависимое решение: '+decision+'.','Способ ответа и критерий: '+method+'.'])
